  2245	        const sc = self.saved_cursor orelse break :saved_cursor null;
  2246	        const pin = self.pages.pin(.{ .active = .{
  2247	            .x = sc.x,
  2248	            .y = sc.y,
  2249	        } }) orelse break :saved_cursor null;
  2250	        try tw.check(.saved_cursor_pin);
